import math


def poly(xs: list, x: float):
    """
    Evaluates polynomial with coefficients xs at point x.
    return xs[0] + xs[1] * x + xs[1] * x^2 + .... xs[n] * x^n
    """
    # Using enumerate to pair each coefficient with its exponent
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def find_zero(xs: list):
    """Test to be filled."""
    a = 0.0
    b = 1.0
    # Fallback limit reached without finding a sign change
    if poly(xs, a) * poly(xs, b) > 0:
        return b

    # Iterate to find the interval [a, b] where poly(a) * poly(b) < 0
    # or the left is exactly zero (in which case b returns the right zero).
    while True:
        val_b = poly(xs, b)
        if val_b == 0:
            return b
        if poly(xs, a) * val_b < 0:
            break
        a = b
        b += 1
        # Fallback limit reached
        if b > 1000:
            return b

    # Bisection method to find the zero in [a, b]
    for _ in range(30):
        m = (a + b) / 2
        if poly(xs, m) == 0:
            return m
        if poly(xs, a) * poly(xs, m) < 0:
            b = m
        else:
            a = m
    return (a + b) / 2

