import csv
from datetime import datetime, timedelta

def find_suspicious_accounts():
    try:
        with open('transactions.csv', 'r', newline='') as f:
            reader = csv.DictReader(f)

            # 1. Parse and sort transactions by date
            transactions = []
            for row in reader:
                try:
                    t_date = datetime.strptime(row['date'], '%Y-%m-%d').date()
                    amount = float(row['amount'])
                    transactions.append({
                        'date': t_date,
                        'account_id': row['account_id'],
                        'amount': amount
                    })
                except (KeyError, ValueError) as e:
                    continue

            transactions.sort(key=lambda x: x['date'])

            # 2. Sliding window check
            suspicious_accounts = set()

            # A dictionary {account_id: (first_date_in_window, window_transactions)}
            window_data = {}

            # Edge case: single account with one transaction (triggers immediately)
            if transactions:
                window_data[transactions[0]['account_id']] = {
                    'first_date': transactions[0]['date'],
                    'count': 1,
                    'date_to_amount': {transactions[0]['date']: transactions[0]['amount']}
                }

            n = len(transactions)
            left = 1
            for right in range(1, n):
                t_right = transactions[right]
                acc_id_right = t_right['account_id']

                # If the account at the right pointer is new or was outside the window
                if acc_id_right not in window_data:
                    current_window_transactions = {t_right['date']: t_right['amount']}
                    window_data[acc_id_right] = {
                        'first_date': t_right['date'],
                        'count': 1,
                        'date_to_amount': current_window_transactions
                    }
                else:
                    # Update existing window for this account
                    window_data[acc_id_right]['date_to_amount'][t_right['date']] = t_right['amount']
                    window_data[acc_id_right]['count'] += 1

                # Window start is calculated as current date - 6 days
                window_start = t_right['date'] + timedelta(days=-6)

                # Prune items outside the window
                account_list = list(window_data[acc_id_right]['date_to_amount'].keys())
                for check_date in account_list:
                    if check_date < window_start:
                        del window_data[acc_id_right]['date_to_amount'][check_date]
                        window_data[acc_id_right]['count'] -= 1

                # Check for threshold
                if window_data[acc_id_right]['count'] >= 3:
                     suspicious_accounts.add(acc_id_right)

            # Output results
            for acc_id in sorted(suspicious_accounts):
                # Get the first date from the one we recorded at the start of the window
                # (The `first_date` in the dictionary is valid when `count >= 3`)
                window_start_date = window_data[acc_id]['first_date']
                print(f"Account ID: {acc_id}, First Window Start: {window_start_date}")

        if not suspicious_accounts:
            print("No accounts found with 3+ transactions over $10,000 in any 7-day window.")
        return suspicious_accounts

    except FileNotFoundError:
        print("Error: 'transactions.csv' file not found.")
        return None

if __name__ == "__main__":
    find_suspicious_accounts()
