def babylonian_squareroot(number):
    if number < 0:
        raise ValueError("Cannot compute square root of a negative number")
    if number == 0:
        return 0
    x = number
    old_x = x
    for __ in range(20):
        x = 0.5 * (x + old_x / x)
        if abs(x - old_x) < 1e-10:
            break
        old_x = x
    return x

