def comb_sort(nums):
    n = len(nums)
    if n <= 1:
        return nums

    gap = n
    shrink = 1.3
    sorted = False

    while not sorted:
        gap = int(gap / shrink)
        if gap <= 1:
            gap = 1
            sorted = True

        i = 0
        while i + gap < n:
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                if gap == 1:
                    sorted = False
            i += 1

    return nums

