import heapq

def k_smallest_pairs(nums1, nums2, k):
    if not nums1 or not nums2:
        return []

    # Using a min-heap. We initially push the pairs formed by the first element of nums1 with all elements of nums2.
    # We store tuples: (sum, index_in_nums1, index_in_nums2)
    heap = []
    for j in range(len(nums2)):
        heapq.heappush(heap, (nums1[0] + nums2[j], 0, j))

    result = []
    visited = set() # To prevent pushing the same pair multiple times

    while heap and len(result) < k:
        current_sum, i, j = heapq.heappop(heap)
        result.append([nums1[i], nums2[j]])

        if i + 1 < len(nums1):
            next_pair_sum = nums1[i + 1] + nums2[j]
            if (i + 1, j) not in visited:
                visited.add((i + 1, j))
                heapq.heappush(heap, (next_pair_sum, i + 1, j))

        if j + 1 < len(nums2):
            next_pair_sum = nums1[i] + nums2[j + 1]
            if (i, j + 1) not in visited:
                visited.add((i, j + 1))
                heapq.heappush(heap, (next_pair_sum, i, j + 1))

    return result

