def is_Sum_Of_Powers_Of_Two(n):
    if n <= 0:
        return False
    while n > 0:
        remainder = n % 2
        if remainder == 1:
            temp = n
            while temp % 2 == 1:
                temp //= 2
            if temp == 0:
                return False
        n //= 2
    return True

