import datetime

def iso_week_number(date_str):
    date = datetime.datetime.strptime(date_str, "%Y-%m-%d").date()
    return f"{date.isocalendar()[0]:04d}-W{date.isocalendar()[1]:02d}"

def count_by_week(dates):
    week_counts = {}
    for date_str in dates:
        week_key = iso_week_number(date_str)
        week_counts[week_key] = week_counts.get(week_key, 0) + 1
    return week_counts
