def get_max_sum(n):
    # Use a dictionary to store computed results (memoization)
    memo = {}

    def f(x):
        # Return the memoized result if it exists
        if x in memo:
            return memo[x]

        # Base case for x values less than 5
        if x < 5:
            res = x

        else:
            # Recursive step: compare the sum of the parts with the current value
            res = max(f(x // 2) + f(x // 4) + f(x // 5) + f(x // 3), x)

        # Store the result in the memoization table before returning
        memo[x] = res
        return res

    return f(n)

