            sorted_flag = True

        i = 0
        while i + gap < n:
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                if gap == 1:
                    sorted_flag = False
            i += 1
    return nums

