from datetime import datetime, timedelta

def merge_shifts(shifts):
    """Merge shifts that overlap or touch, drop merged shifts shorter than 15 minutes.
    Return the merged shifts as (start, end) tuples sorted by start."""
    if not shifts:
        return []

    # Convert "HH:MM" strings to datetime.time objects for easy comparison
    def parse_time(time_str):
        return datetime.strptime(time_str, "%H:%M").time()

    # Convert to list of (start_datetime, end_datetime) for easier comparison
    shifts_dt = []
    for start_str, end_str in shifts:
        start = datetime.combine(datetime.min, parse_time(start_str))
        end = datetime.combine(datetime.min, parse_time(end_str))
        shifts_dt.append((start, end))

    # Sort shifts by start time
    shifts_dt.sort(key=lambda x: x[0])

    merged = []
    current_start, current_end = shifts_dt[0]

    for start, end in shifts_dt[1:]:
        if start <= current_end:  # Overlap or touch (start <= current_end)
            # Merge by setting current_end to the later end time
            current_end = max(current_end, end)
        else:
            # No overlap, check if the current shift is at least 15 minutes
            if current_end - current_start >= timedelta(minutes=15):
                merged.append((current_start, current_end))
            # Start a new current shift
            current_start, current_end = start, end

    # Don't forget to add the last shift to merged list
    if current_end - current_start >= timedelta(minutes=15):
        merged.append((current_start, current_end))

    # Convert back to (start, end) tuples with "HH:MM" strings
    def format_time(dt):
        return dt.strftime("%H:%M")

    result = []
    for start, end in merged:
        result.append((format_time(start), format_time(end)))

    return result
```

