import datetime

def iso_year_week(date):
    date = datetime.date(int(date[:4]), int(date[5:7]), int(date[8:10]))
    return "{:%Y-W%W}".format(date)

def count_by_week(dates):
    count = {}
    for date in dates:
        week = iso_year_week(date)
        count[week] = count.get(week, 0) + 1
    return count
